/* Real duplicate engine, native readers and panel controller. No physical input. */
#define wWinMain duplicate_unused_entrypoint
#include "../app/fpduplicates.c"
#undef wWinMain
#include "../linux/fpsha256.h"
static int passed,failed;static wchar_t fixture[32768];
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL %d %s (error %lu)\n",__LINE__,label,(unsigned long)GetLastError());}}while(0)
static void path(wchar_t out[32768],const wchar_t *rel){swprintf(out,32768,L"%ls\\%ls",fixture,rel);}
static int put(const wchar_t *rel,const void *bytes,DWORD count,int replace){wchar_t p[32768];path(p,rel);HANDLE h=CreateFileW(p,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,replace?CREATE_ALWAYS:CREATE_NEW,0,NULL);if(h==INVALID_HANDLE_VALUE)return 0;DWORD n;int ok=WriteFile(h,bytes,count,&n,NULL)&&n==count;CloseHandle(h);return ok;}
static void setup(void){wchar_t temp[32768],p[32768],a[32768];GetTempPathW(32768,temp);swprintf(fixture,32768,L"%lsopenpilot-duplicates-%lu-%llu",temp,GetCurrentProcessId(),(unsigned long long)GetTickCount64());CHECK("unique owned fixture",CreateDirectoryW(fixture,NULL));path(p,L"nested");CHECK("nested folder",CreateDirectoryW(p,NULL));CHECK("first content",put(L"a.txt","same content",12,0));CHECK("equal nested content",put(L"nested\\b.txt","same content",12,0));CHECK("same-size different content",put(L"different.txt","same contenX",12,0));CHECK("first empty",put(L"zero1",NULL,0,0));CHECK("second empty",put(L"zero2",NULL,0,0));CHECK("unique size",put(L"unique","u",1,0));path(a,L"a.txt");path(p,L"alias.txt");CHECK("hardlink fixture",CreateHardLinkW(p,a,NULL));path(p,L"loop");CHECK("reparse fixture",CreateSymbolicLinkW(p,fixture,SYMBOLIC_LINK_FLAG_DIRECTORY|2)||CreateSymbolicLinkW(p,fixture,SYMBOLIC_LINK_FLAG_DIRECTORY));}
static duplicate_result scan(const wchar_t *const *roots,uint32_t n,HANDLE cancel,duplicate_notify cb,void *user){duplicate_result r;duplicates_scan(roots,n,1,0,cancel,cb,user,&r);return r;}
static void test_duplicate_windows_groups_and_aliases(void){const wchar_t *roots[]={fixture};duplicate_result r=scan(roots,1,NULL,NULL,NULL);CHECK("complete Windows scan",r.state==DUP_COMPLETE&&!r.errors);CHECK("two verified groups only",r.groups==2&&r.members==4&&r.duplicate_bytes==12);CHECK("hardlinks and reparse entries excluded",r.aliases==1&&r.skipped==1);CHECK("unique-size file was not hashed",r.count==6&&r.hashed==5);int valid=1;for(uint32_t i=0;i<r.members;i++)if(!r.files[i].group||!wcscmp(r.files[i].relative,L"different.txt")||!wcscmp(r.files[i].relative,L"alias.txt"))valid=0;CHECK("only verified independent copies are visible",valid);duplicates_free(&r);
 wchar_t nested[32768];path(nested,L"nested");const wchar_t *overlap[]={nested,fixture,fixture};r=scan(overlap,3,NULL,NULL,NULL);CHECK("nested and repeated roots scan once",r.state==DUP_COMPLETE&&r.groups==2&&r.members==4&&r.count==6);duplicates_free(&r);
 uint8_t *data=malloc(DU_BLOCK*2+7);for(uint32_t i=0;i<DU_BLOCK*2+7;i++)data[i]=(uint8_t)(i*31);CHECK("large file fixtures",put(L"large1",data,DU_BLOCK*2+7,0)&&put(L"large2",data,DU_BLOCK*2+7,0));free(data);r=scan(roots,1,NULL,NULL,NULL);CHECK("multi-block and short-final-block comparison",r.state==DUP_COMPLETE&&r.groups==3&&r.members==6&&r.duplicate_bytes==DU_BLOCK*2+19);duplicates_free(&r);wchar_t p[32768];path(p,L"large1");DeleteFileW(p);path(p,L"large2");DeleteFileW(p);}
typedef struct control {HANDLE cancel;uint32_t phase;int fired,mutate;} control;
static void interrupt(void *user,const duplicate_progress *p){control *c=user;if(!c->fired&&p->phase==c->phase){c->fired=1;if(c->mutate)put(L"nested\\b.txt","changed data",12,1);else SetEvent(c->cancel);}}
static void test_duplicate_cancellation_mutation_and_partial(void){const wchar_t *roots[]={fixture};HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);duplicate_result r=scan(roots,1,cancel,NULL,NULL);CHECK("pre-cancelled is incomplete",r.state==DUP_STOPPED&&!r.groups);duplicates_free(&r);for(uint32_t phase=DUP_ENUMERATE;phase<=DUP_VERIFYING;phase++){ResetEvent(cancel);control c={cancel,phase,0,0};r=scan(roots,1,cancel,interrupt,&c);CHECK("each phase cancellation is truthful",c.fired&&r.state==DUP_STOPPED&&!r.groups);duplicates_free(&r);}ResetEvent(cancel);control c={cancel,DUP_VERIFYING,0,1};r=scan(roots,1,cancel,interrupt,&c);CHECK("same-size mutation between hash and compare fails closed",c.fired&&r.state==DUP_PARTIAL&&r.errors&&r.groups==1&&r.members==2);duplicates_free(&r);CHECK("restore mutated file",put(L"nested\\b.txt","same content",12,1));wchar_t p[32768];path(p,L"a.txt");HANDLE lock=CreateFileW(p,GENERIC_READ,0,NULL,OPEN_EXISTING,0,NULL);CHECK("owned read lock",lock!=INVALID_HANDLE_VALUE);r=scan(roots,1,NULL,NULL,NULL);CHECK("unreadable files leave partial status",r.state==DUP_PARTIAL&&r.errors&&r.groups==1);duplicates_free(&r);if(lock!=INVALID_HANDLE_VALUE)CloseHandle(lock);duplicate_result disabled;const wchar_t *linux[]={L"\\\\wsl.localhost\\Ubuntu\\tmp"};duplicates_scan(linux,1,0,0,NULL,NULL,NULL,&disabled);CHECK("disabled WSL never falls back to provider reads",disabled.state==DUP_PARTIAL&&disabled.errors);duplicates_free(&disabled);CloseHandle(cancel);}
static duplicate_file file_info(du_reader *r,const wchar_t *relative){wchar_t p[32768];path(p,relative);HANDLE h=CreateFileW(p,FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);BY_HANDLE_FILE_INFORMATION i;GetFileInformationByHandle(h,&i);CloseHandle(h);duplicate_file f={.relative=(wchar_t*)relative,.scan={((uint64_t)i.nFileSizeHigh<<32)|i.nFileSizeLow,i.dwVolumeSerialNumber,((uint64_t)i.nFileIndexHigh<<32)|i.nFileIndexLow}};CHECK("reader opens observed identity",!duplicate_reader_open(r,relative,&f.scan));CHECK("local SHA succeeds",!duplicate_reader_hash(r,f.hash));f.hashed=r->stamp;return f;}
static void test_duplicate_exact_comparison_and_root_guard(void){du_reader a={0},b={0};CHECK("two rooted Windows readers",!duplicate_reader_init(&a,fixture,0,0,NULL)&&!duplicate_reader_init(&b,fixture,0,0,NULL));duplicate_file x=file_info(&a,L"a.txt"),y=file_info(&b,L"different.txt");memcpy(y.hash,x.hash,32);DWORD e;CHECK("forced digest collision still differs by bytes",duplicates_equal(&a,&b,&x,&y,NULL,&e)==0&&!e);CHECK("reader refuses traversal",duplicate_reader_open(&a,L"nested\\..\\a.txt",&x.scan)!=0);CHECK("reader refuses named streams",duplicate_reader_open(&a,L"a.txt:stream",&x.scan)!=0);CHECK("reader refuses reparse ancestor",duplicate_reader_open(&a,L"loop\\a.txt",&x.scan)!=0);y=file_info(&b,L"nested\\b.txt");CHECK("exact byte match succeeds",duplicates_equal(&a,&b,&x,&y,NULL,&e)==1&&!e);CHECK("mutate hashed file",put(L"nested\\b.txt","changed data",12,1));CHECK("post-hash mutation is not equality",duplicates_equal(&a,&b,&x,&y,NULL,&e)==-1&&e==ERROR_FILE_INVALID);put(L"nested\\b.txt","same content",12,1);y=file_info(&b,L"nested\\b.txt");wchar_t replacement[32768];path(replacement,L"nested\\b.txt");duplicate_reader_free(&b);DeleteFileW(replacement);CHECK("replace hashed path with new identity",put(L"nested\\b.txt","same content",12,0));CHECK("replacement reader",!duplicate_reader_init(&b,fixture,0,0,NULL));CHECK("path replacement is not the scanned file",duplicates_equal(&a,&b,&x,&y,NULL,&e)==-1&&e==ERROR_FILE_INVALID);duplicate_reader_free(&a);duplicate_reader_free(&b);CHECK("result path rules reject escapes and empty components",duplicate_relative_safe(L"nested\\b.txt")&&!duplicate_relative_safe(L"..\\x")&&!duplicate_relative_safe(L"nested\\\\b")&&!duplicate_relative_safe(L"a:stream")&&!duplicate_relative_safe(L"/etc/passwd"));}
static void join_panel(void){uint64_t until=GetTickCount64()+15000;while(A.thread&&GetTickCount64()<until){Sleep(5);tick();}}
static void test_duplicate_panel_worker_lifecycle_and_pixels(void){InitializeCriticalSection(&A.lock);A.dpi=96;A.shown=1;A.selected=-1;A.out=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);A.cancel=CreateEventW(NULL,TRUE,FALSE,NULL);fonts();HANDLE section=CreateFileMappingW(INVALID_HANDLE_VALUE,NULL,PAGE_READWRITE,0,620*780*8,NULL);CHECK("real pixel mapping",map(section,620,780));duplicate_open request={.session=123,.count=1,.chars={(uint32_t)wcslen(fixture)+1}};queue(&request,fixture);CHECK("explicit root starts worker",A.thread&&!A.ready);join_panel();CHECK("panel publishes joined verified groups",!A.thread&&A.ready&&A.result.state==DUP_COMPLETE&&A.result.members==4);A.request.wsl=1;A.run_wsl=1;struct {panelp_head h;uint32_t enabled;} policy={{PANELP_DUPLICATE_WSL_POLICY,4},0};on_host((msg*)&policy);CHECK("policy intake preserves completed Windows results and captured worker policy",!A.request.wsl&&!A.queued_request.wsl&&A.run_wsl==1&&A.ready&&A.result.state==DUP_COMPLETE);begin();join_panel();CHECK("next Windows worker captures disabled WSL policy",!A.thread&&!A.run_wsl&&A.ready&&A.result.state==DUP_COMPLETE);uint32_t generation=A.generation;queue(&request,fixture);CHECK("replayed request preserves generation",A.generation==generation&&!A.thread);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_DOWN});CHECK("keyboard selects next file",A.selected==1);A.shown=0;paint();CHECK("hidden panel retains results",A.ready&&A.result.groups==2);A.shown=1;paint();uint32_t *pixels=A.pixels;int colored=0;for(int i=0;i<A.w*A.h;i++)if((pixels[i]&0xffffff)!=(pixels[0]&0xffffff)){colored=1;break;}CHECK("list and controls paint real pixels",colored);wchar_t shot[32768];if(GetEnvironmentVariableW(L"OPENPILOT_DUPLICATE_SCREENSHOT",shot,32768)){BITMAPINFOHEADER bi={sizeof bi,A.w,-A.h,1,32,BI_RGB};BITMAPFILEHEADER fh={.bfType=0x4d42,.bfSize=(DWORD)(sizeof fh+sizeof bi+A.w*A.h*4),.bfOffBits=sizeof fh+sizeof bi};HANDLE f=CreateFileW(shot,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(f!=INVALID_HANDLE_VALUE){io(f,&fh,sizeof fh,1);io(f,&bi,sizeof bi,1);io(f,A.pixels,A.w*A.h*4,1);CloseHandle(f);}}
 input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_F5});CHECK("refresh invalidates results and increments generation",A.thread&&!A.ready&&A.generation!=generation);request.session=124;queue(&request,fixture);CHECK("replacement queues behind cancel and join",A.queued_request.session==124);join_panel();CHECK("new session replaces old worker safely",!A.thread&&A.ready&&A.request.session==124&&A.result.state==DUP_COMPLETE);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_F5});input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_ESCAPE});join_panel();CHECK("Escape stops without a refresh loop",!A.thread&&A.result.state==DUP_STOPPED);CloseHandle(A.out);CloseHandle(A.cancel);duplicates_free(&A.result);duplicates_free(&A.work);for(uint32_t i=0;i<DUP_ROOTS;i++){free(A.roots[i]);free(A.queued[i]);}if(A.shared)UnmapViewOfFile(A.shared);CloseHandle(A.section);SelectObject(A.dc,A.original);DeleteObject(A.bitmap);DeleteDC(A.dc);DeleteObject(A.font);DeleteObject(A.bold);DeleteCriticalSection(&A.lock);memset(&A,0,sizeof A);}
static void test_duplicate_native_linux_and_cross_endpoint(void){wchar_t linux[32768];DWORD n=GetEnvironmentVariableW(L"OPENPILOT_DUPLICATE_WSL_FIXTURE",linux,32768);CHECK("owned native Linux fixture supplied",n&&n<32768);if(!n||n>=32768)return;const wchar_t *roots[]={linux};duplicate_result r=scan(roots,1,NULL,NULL,NULL);CHECK("native Linux hash and exact verification",r.state==DUP_COMPLETE&&!r.errors&&r.groups==1&&r.members==2&&r.duplicate_bytes==11);CHECK("native special files and hardlinks excluded",r.skipped==2&&r.aliases==1);du_reader na={0},nb={0};CHECK("native stable metadata readers",!duplicate_reader_init(&na,linux,1,0,NULL)&&!duplicate_reader_init(&nb,linux,1,0,NULL));duplicate_file file={0};for(uint32_t i=0;i<r.count;i++)if(!wcscmp(r.files[i].relative,L"a.txt"))file=r.files[i];/* The hardlink representative may be alias.txt instead. */if(!file.relative)for(uint32_t i=0;i<r.count;i++)if(!wcscmp(r.files[i].relative,L"alias.txt"))file=r.files[i];CHECK("native observed identity opens",file.relative&&!duplicate_reader_open(&na,file.relative,&file.scan));CHECK("native digest captured",!duplicate_reader_hash(&na,file.hash));file.hashed=na.stamp;DWORD err;CHECK("native exact stable bytes",duplicates_equal(&na,&nb,&file,&file,NULL,&err)==1&&!err);wchar_t changed[32768];swprintf(changed,32768,L"%ls\\a.txt",linux);HANDLE h=CreateFileW(changed,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);DWORD wrote=0;CHECK("owned native mutation",h!=INVALID_HANDLE_VALUE&&WriteFile(h,"changed data",12,&wrote,NULL)&&wrote==12);if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);CHECK("native post-hash mutation is rejected",duplicates_equal(&na,&nb,&file,&file,NULL,&err)==-1&&err);h=CreateFileW(changed,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);CHECK("native content restored",h!=INVALID_HANDLE_VALUE&&WriteFile(h,"same content",12,&wrote,NULL)&&wrote==12);if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);duplicate_reader_free(&na);duplicate_reader_free(&nb);int colon=0,raw=0;for(uint32_t i=0;i<r.members;i++){if(wcschr(r.files[i].relative,0xf03a))colon=1;if(wcschr(r.files[i].relative,0xdcff))raw=1;}CHECK("punctuation and invalid UTF8 names roundtrip",colon&&raw);duplicates_free(&r);const wchar_t *both[]={fixture,linux};r=scan(both,2,NULL,NULL,NULL);CHECK("Windows and Linux copies grouped together",r.state==DUP_COMPLETE&&r.groups==3&&r.members==8&&r.duplicate_bytes==35);duplicates_free(&r);du_reader reader={0};CHECK("persistent native reader opens",!duplicate_reader_init(&reader,linux,1,0,NULL));du_stamp fake={0};CHECK("native reader rejects traversal",duplicate_reader_open(&reader,L"..\\outside",&fake)!=0);CHECK("native FIFO read rejected without blocking",duplicate_reader_open(&reader,L"fifo",&fake)!=0);CHECK("native symlink read rejected",duplicate_reader_open(&reader,L"loop\\a.txt",&fake)!=0);duplicate_reader_free(&reader);}
static void cleanup(void){const wchar_t *files[]={L"a.txt",L"alias.txt",L"nested\\b.txt",L"different.txt",L"zero1",L"zero2",L"unique"};wchar_t p[32768];for(uint32_t i=0;i<sizeof files/sizeof *files;i++){path(p,files[i]);DeleteFileW(p);}path(p,L"loop");RemoveDirectoryW(p);path(p,L"nested");RemoveDirectoryW(p);RemoveDirectoryW(fixture);}
int wmain(void){SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);setup();test_duplicate_windows_groups_and_aliases();test_duplicate_cancellation_mutation_and_partial();test_duplicate_exact_comparison_and_root_guard();test_duplicate_panel_worker_lifecycle_and_pixels();test_duplicate_native_linux_and_cross_endpoint();cleanup();printf("%d passed, %d failed; 5 duplicate selectors\n",passed,failed);return failed?1:0;}
